// @generated by the slice schematic 1.2.0 from its spec. Edit in place; reshape via the spec and --force.
import { TestBed } from '@angular/core/testing';
import { MembersViewModel } from './members.view-model';
import { MemberService } from '../member/member.service';

describe('MembersViewModel', () => {
  let vm: MembersViewModel;

  beforeEach(() => {
    TestBed.configureTestingModule({ providers: [MembersViewModel] });
    vm = TestBed.inject(MembersViewModel);
  });

  it('lists every record by default', () => {
    expect(vm.filtered().length).toBe(TestBed.inject(MemberService).members().length);
  });

  it('filters by the search fields', () => {
    const service = TestBed.inject(MemberService);
    const created = service.create({
      name: 'Test name',
      tier: 'Standard',
      standing: 'Good',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    vm.searchQuery.set('Test name'.toLowerCase());
    expect(vm.filtered().map((item) => item.id)).toContain(created.id);
    vm.searchQuery.set('no record contains this');
    expect(vm.filtered()).toEqual([]);
  });

  it('narrows the list when the standing filter is on', () => {
    const service = TestBed.inject(MemberService);
    const matching = service.create({
      name: 'Test name',
      tier: 'Standard',
      standing: 'Blocked',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    const other = service.create({
      name: 'Test name',
      tier: 'Standard',
      standing: 'Good',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    vm.toggleStandingFilter();
    expect(vm.filtered().every((item) => item.standing === 'Blocked')).toBe(true);
    expect(vm.filtered().map((item) => item.id)).toContain(matching.id);
    expect(vm.filtered().map((item) => item.id)).not.toContain(other.id);
  });

  it('creates a record through save when nothing is being edited', () => {
    const service = TestBed.inject(MemberService);
    const before = service.members().length;
    vm.startCreate();
    vm.save({
      name: 'Test name',
      tier: 'Standard',
      standing: 'Good',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    expect(service.members().length).toBe(before + 1);
    expect(vm.editing()).toBeNull();
  });

  it('removes a record', () => {
    const service = TestBed.inject(MemberService);
    const created = service.create({
      name: 'Test name',
      tier: 'Standard',
      standing: 'Good',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    vm.remove(created.id);
    expect(service.byId(created.id)).toBeUndefined();
  });

  it('resolves the record being edited once startEdit runs', () => {
    const service = TestBed.inject(MemberService);
    const created = service.create({
      name: 'Test name',
      tier: 'Standard',
      standing: 'Good',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    expect(vm.editingMember()).toBeUndefined();
    vm.startEdit(created.id);
    expect(vm.editingMember()?.id).toBe(created.id);
  });

  it('updates rather than creates when a record is being edited', () => {
    const service = TestBed.inject(MemberService);
    const created = service.create({
      name: 'Test name',
      tier: 'Standard',
      standing: 'Good',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    const before = service.members().length;
    vm.startEdit(created.id);
    vm.save({
      name: 'Changed',
      tier: 'Standard',
      standing: 'Good',
      status: 'Active',
      city: 'Test city',
      joinedOn: '2026-01-01',
      loanLimit: 1,
      notes: '',
    });
    expect(service.members().length).toBe(before);
    expect(service.byId(created.id)?.name).toEqual('Changed');
    expect(vm.editing()).toBeNull();
  });

  it('falls back to a default badge variant for an unlisted standing', () => {
    expect(vm.standingVariant('not a listed value')).toBe('secondary');
  });

  it('falls back to a default badge variant for an unlisted status', () => {
    expect(vm.statusVariant('not a listed value')).toBe('outline');
  });
});
